///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.searchQnaResult
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchQnaResult = async function () {
    /* sdd-asis-lifecycle:begin fn_searchQnaResult — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.QnaForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_searchQnaResultReq').set('method', 'searchQnaResult');
    { const nr = await scwin.tx_fn_searchQnaResult(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil17101/jldfil17101.xml", { "method": 'searchQnaResult' }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goRegister
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goRegister = async function () {
    /* sdd-asis-lifecycle:begin fn_goRegister — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.QnaForm || { elements: [] });
    $c.util.getComponent('dma_searchQnaResultReq').set('method', 'searchQnaApply');
    frm.action = 'qna.do';
    await scwin.tx_fn_goRegister();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.QnaForm || { elements: [] });
    if ($c.cm.fn_NullChk($c.util.getComponent('slc_jobType'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_title'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('txa_content'))) {
        return;
    }
    frm.action = 'qna.do';
    $c.util.getComponent('dma_searchQnaResultReq').set('method', 'registerQna');
    await scwin.tx_fn_register();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkByte
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.checkByte = async function (_obj) {
    /* sdd-asis-lifecycle:begin fn_CheckByte — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const standardByte = 2000;
    const contnByte = scwin.getByte(_obj);
    const byteCntObj = $c.util.getComponent("txt_byteCnt");
    byteCntObj.innerText = "질의내용(" + (contnByte) + "/2000 byte)";
    if (contnByte > standardByte) {
        await $c.win.alert((contnByte - standardByte) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();
        _obj.setValue(scwin.calcContn(contnValue, standardByte));
        await scwin.checkByte(_obj);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getByte
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.getByte = function (_obj) {
    /* sdd-asis-lifecycle:begin fn_GetByte — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const sTmpCntnt = new String(_obj.getValue());
    let iCounts = 0;
    for (let i = 0; i < sTmpCntnt.length; i++) {
        const escapeChar = escape(sTmpCntnt.charAt(i));
        if (escapeChar === '%0D') {
            iCounts++;
        } else {
            if (escapeChar.length > 4) {
                iCounts += 2;
            } else {
                iCounts++;
            }
        }
    }
    return iCounts;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.calcContn
 * @author Inswave
 * @date 2026. 09. 29
 * @param _contn _maximum
 * @returns
 * @hidden N
*/
scwin.calcContn = function (_contn, _maximum) {
    /* sdd-asis-lifecycle:begin fn_CalcContn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let rContn = "";
    let nbytes = 0;
    for (let i = 0; i < _contn.length; i++) {
        const ch = _contn.charAt(i);
        let inc = 0;
        if (escape(ch) === '%0D') {
            inc = 1;
        } else {
            if (escape(ch).length > 4) {
                inc = 2;
            } else {
                if (ch === '<' || ch === '>') {
                    inc = 4;
                } else {
                    inc = 1;
                }
            }
        }
        nbytes += inc;
        if (nbytes > _maximum) {
            break;
        }
        rContn += ch;
    }
    return rContn;
    /* sdd-asis-lifecycle:end */
};
